#!/bin/bash
set -eo pipefail
set -C
task_base='/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001'
task_root="$task_base/execution_v1"
task_python='/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python'
date -u '+DEPLOYMENT_COLLECTION_UTC=%Y-%m-%dT%H:%M:%SZ'
printf 'OWN_READONLY_GPU_PARTITION_SNAPSHOT\n'
sinfo -p hgpu2p,hgpu4,hgpu8 -N -O nodelist,gres,gresused,cpusstate
test "$(id -un)" = sunyiq
test -d "$task_base"
test "$(readlink -e "$task_base")" = "$task_base"
test ! -e "$task_root"
test ! -L "$task_root"
test -x "$task_python"
mkdir "$task_root"
mkdir "$task_root/logs"
printf '%s'  | base64 -d > "$task_root/OWN_EXECUTION_PAYLOAD.tar.gz"
"$task_python" -B -X utf8 -c 'import gzip,hashlib,io,json,os,pathlib,stat,sys,tarfile
r=pathlib.Path(sys.argv[1]);p=r/'"'"'OWN_EXECUTION_PAYLOAD.tar.gz'"'"'
assert str(r)=='"'"'/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001/execution_v1'"'"'
assert r.resolve(strict=True)==r and all(not x.is_symlink() for x in (r,*r.parents))
b=p.read_bytes();assert len(b)<=10485760 and hashlib.sha256(b).hexdigest()==sys.argv[2]
d=gzip.decompress(b);assert len(d)<=67108864
t=tarfile.open(fileobj=io.BytesIO(d),mode='"'"'r:'"'"');m=t.getmembers()
assert len(m)<=151 and len({x.name for x in m})==len(m)
assert all(x.isfile() and not x.issym() and not x.islnk() and 0<x.size<=16777216 for x in m)
assert all(not pathlib.PurePosixPath(x.name).is_absolute() and '"'"'..'"'"' not in pathlib.PurePosixPath(x.name).parts for x in m)
manifest=t.extractfile('"'"'OWN_DEPLOYMENT_MANIFEST.json'"'"').read();assert hashlib.sha256(manifest).hexdigest()==sys.argv[3]
items=json.loads(manifest)['"'"'files'"'"'];assert len({x['"'"'relative_path'"'"'] for x in items})==len(items)
assert {x.name for x in m}=={x['"'"'relative_path'"'"'] for x in items}|{'"'"'OWN_DEPLOYMENT_MANIFEST.json'"'"'}
verified={}
for x in items:
 b=t.extractfile(x['"'"'relative_path'"'"']).read();assert len(b)==x['"'"'bytes'"'"'] and hashlib.sha256(b).hexdigest()==x['"'"'sha256'"'"'];verified[x['"'"'relative_path'"'"']]=b
verified['"'"'OWN_DEPLOYMENT_MANIFEST.json'"'"']=manifest
for name,b in verified.items():
 q=r/name;q.parent.mkdir(parents=True,exist_ok=True)
 assert all(not x.is_symlink() for x in (q.parent,*q.parent.parents))
 with q.open('"'"'xb'"'"') as f:f.write(b)
a=json.loads((r/'"'"'contracts/US_INPUT_ACCEPTANCE_v1.json'"'"').read_bytes())
c=pathlib.Path('"'"'/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001/common_preparation_v2/reports/COMMON_INPUT_CANDIDATE_v1'"'"')
assert c.resolve(strict=True)==c and all(not x.is_symlink() for x in (c,*c.parents))
assert a['"'"'source_remote_candidate_root'"'"']==str(c) and a['"'"'status'"'"']=='"'"'PASS_NEW_COMMON_US_INPUT_VERSION'"'"'
decision=json.loads((r/'"'"'review/TRAINING_EXECUTION_DECISION_v1.json'"'"').read_bytes())
assert decision['"'"'allowed'"'"'] is True and decision['"'"'synthetic_gpu_capacity_probe_allowed'"'"'] is True
assert set(a['"'"'array_files'"'"'])=={'"'"'train_weather'"'"','"'"'dev_weather'"'"','"'"'train_q'"'"','"'"'dev_q'"'"','"'"'static'"'"'}
for name,item in a['"'"'array_files'"'"'].items():
 source=c/(name+'"'"'.npy'"'"');destination=r/'"'"'accepted_inputs'"'"'/(name+'"'"'.npy'"'"')
 assert item['"'"'file'"'"']==name+'"'"'.npy'"'"' and decision['"'"'bound_file_sha256'"'"']['"'"'accepted_inputs/'"'"'+name+'"'"'.npy'"'"']==item['"'"'sha256'"'"']
 fd=os.open(source,os.O_RDONLY|os.O_NOFOLLOW)
 with os.fdopen(fd,'"'"'rb'"'"') as f:
  before=os.fstat(f.fileno());assert stat.S_ISREG(before.st_mode) and before.st_nlink==1 and 0<before.st_size<=134217728
  h=hashlib.sha256();count=0
  with destination.open('"'"'xb'"'"') as out:
   while True:
    chunk=f.read(1048576)
    if not chunk:break
    count+=len(chunk);h.update(chunk);out.write(chunk)
   out.flush();os.fsync(out.fileno())
  after=os.fstat(f.fileno());named=os.stat(source,follow_symlinks=False)
  fields=lambda s:(s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
  assert fields(before)==fields(after)==fields(named)
  assert count==item['"'"'bytes'"'"'] and h.hexdigest()==item['"'"'sha256'"'"']
  assert destination.stat().st_size==count and hashlib.sha256(destination.read_bytes()).hexdigest()==item['"'"'sha256'"'"']
print('"'"'OWN_EXECUTION_PACKAGE_VERIFIED_FILES='"'"'+str(len(verified)))
print('"'"'OWN_ACCEPTED_COMMON_ARRAYS_COPIED=5'"'"')
' "$task_root" a8687b604014bc01596d37aab0956e55b6baf165eb289c4e43485d5030d4b475 22e8533da96972d8245231eb947f12b5b4bee7fd95e0f6162f27a8c5b634efc5
set +e
out=$(sbatch "$task_root/remote/run_six_us_repairs_v1.sbatch" 2>&1)
submit_exit=$?
set -e
printf '%s\n' "$out"
printf 'OWN_SIX_SUBMIT_EXIT=%s\n' "$submit_exit"
test "$submit_exit" -eq 0
job=$(printf '%s\n' "$out" | sed -n 's/^Submitted batch job \([0-9][0-9]*\)$/\1/p')
if [ -z "$job" ] || [ "$(printf '%s\n' "$job" | wc -l)" -ne 1 ]; then
  printf 'STOP_NO_UNIQUE_SUBMISSION_ACKNOWLEDGEMENT\n'
  exit 1
fi
printf '%s\n' "$job" > "$task_root/OWN_SIX_TRAINING_JOB_ID.txt"
printf 'OWN_SIX_TRAINING_JOB_ID=%s\n' "$job"
squeue -j "$job" -h -o '%i|%j|%T|%R'
sacct -j "$job" -n -P -o JobIDRaw,JobName,State,ExitCode,Elapsed,AllocCPUS,ReqTRES,AllocTRES
printf 'OWN_SIX_COLLECTION_DONE\n'
